) AS (
  VALUES 
    (306::BIGINT, 'No es malo, pero no es bueno. La verdad no me gusto la forma en la que explica usa presentaciones y explica lo mismo que el libro pero más difícil de entender ya que no se le entiende muy bien los rayones que hace. Con solo quizzes y tareas se pasa fácil'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '938594c18b5fafbaae190efd56c2d064ef1e32dabfe3702d338612d930f694e0'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Un profesor muy neutral la verdad, el mae no es mala nota y las evaluaciones son nivel humano, o sea no tan matadas. El problema es que las clases son ABURRIDAS, solo es leer un PowerPoint con recortes de un libro, al menos las deja grabadas. Estaría bien que hiciera programas ejemplo en tiempo real'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7b04a6d5c38d518168a5c82df4faf71b2f2e2782b499f7a1cb4e8a3031913b64'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Cada semana hay quiz, lab (no hace falta conectarse a la clase) y una lectura semanal. NO explica nada, se pasa siendo autodidacto. Hágase un calendario desde s1, son muchas evaluaciones fáciles de olvidar. Usa un autograder, entonces es un 100 o un 0. Si no le gusta programar, llévelo VIRTUAL.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '3939cce96be5be6ed9a3e4c4b7cbcba67b2f29d7283027fbdb2e5edcf6a925fe'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Lo mejor que este profesor puede hacer por el curso es pensionarse'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-09T00:00:00+00:00'::TIMESTAMPTZ, '755f27cd21cd819334baccd9fd80e17b699be966719ba20151ab3fe0daa9d395'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'clases igual de ridículas e inentendibes que su nombre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-01-18T00:00:00+00:00'::TIMESTAMPTZ, '8d683530a9b1d97d7bdd696e6a676a2bcded284b8680a4f73cb2ea47722ea132'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'El es super arrogante, te baja puntos en los examenes porque te falta una coma o un parentesis, lo unico que hae es explicar lo mismo del libro, los quices son confusos y los proyectos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-10-20T00:00:00+00:00'::TIMESTAMPTZ, '1a21a1f2f713203109d29110b47c55b90c30d914db9f2f76af07a6e0f26aaa68'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Clases aburridas, se dedica a leer un libro, del cual también deja la tarea de resumirlo, cero pasión por enseñar, actitud arrogante, quices confusos, tal vez pueda pasar el curso pero no va a aprender absolutamente nada, si puede evitarlo, hágalo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-09-10T00:00:00+00:00'::TIMESTAMPTZ, '926a566170c2f0c94e2b1926ec639544e5ee1e2f331a3f9992071c375dcf4750'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'En modalidad virtual la clase se basa en leer un libro en inglés, y hacer quices y laboratorios todas las semanas que valen 1%, más dos parciales y tres proyectos. Es un poco arrogante y casi no ayuda cuando usted le pide ayuda. Si usted es autodidacta y aprende solo llévelo con él.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'b29884f017265ae238da625815a246e2c1377d394343dcc473e8a245abe67aa3'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Prácticamente no dio clases, el curso consiste en leer un libro (en inglés) y hacer quices TODAS las semanas. Solo hay que conectarse para que el profe vuelva a leer lo que uno ya leyó.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '99a9dd701c4f9237aae12a6857a3cdcc48e144caf7a417cac1baa9fbb08afffe'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Mi tata se quiebra la espalda para pagar impuestos para que le paguen a este profesor que lo único que hace es subir un libro y decir lo que dice el libro. El curso se basa en leer un libro y ya, no es necesario el profesor, cero pasión por enseñar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-03-13T00:00:00+00:00'::TIMESTAMPTZ, '427e7edae5086eccaeebff954b3825c990b0e6f7274753ad246726e6c9303982'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Si uno quiere ser autodidacta, lleve este profe, de ahí en fuera no lo recomiendo en absoluto. Todo es leer un libro sobre programar en inglés que es muy largo y hay que hacerlo semanalmente y todo se evalúa con el mismo. Los laboratorios si lee a conciencia si salen, y los quices son algo confusos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'c558d95f47926af40d6795c31061e1968a27436ddad7d41b7939c5b34d88410c'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Sesion de 2 horas de aburrimiento con quices demasiado confusos y examenes aun mas confusos. No es imposible pasar con el mae pero preparese para la peor clase de su semestre'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'da88be49dff04a8ec64f4eddfc097599da6b9e9dc23372a38d49ca9cd08cb448'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Es un asco de profesor, solo quiere que uno lea y no explica nada. Cree que los laboratorios se pueden hacer en un tiempo limite y el tiempo lo escoge el sin parametros de nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2024-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'e40347f5709c0d7cdfdd6617fc0625100c47b2df59535654910adee07f1e6a47'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Es un muy mal profesor, no explica nada bien, los proyectos no se evaluan tal cual en la rúbrica y sus clases son sumamente lentas y aburridas. En mi humilde opinión lo mejor que puede hacer es pensionarse.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'af1b1fa1666806788258487562c2800455a9f5ce1e808a4ea6ad3e2462540c9b'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Clases sumamente aburridas y poco claras, quices duros y los examenes son las mismas preguntas que los quices. No recomendado pero se puede pasar'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c82ee8ddca84eb83dc25493bc2aac3acce62a24c609c714c535cd8805f63b683'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Sus clases tiene un ritmo muy lento y aburrido, aunque es un buen profesor e intenta explicar lo mejor posible. Hace quices confusos, los exámenes son exactamente igual que los quices, hasta utiliza las misma preguntas cambiando solo una palabra. Las tareas son muy sencillas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6d2c80585b9e18e83ba7bf24a8a83a93b170d7f68ccb080d78c8f43239275786'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'No recomiendo que lleven el curso con él si quieren pasar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'c5ab137ecbebbddfb7c23ddc4c6ca2052441059bce09ef63486928c1a453f622'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'No es imposible pasar con él, las clases se basan en un libro. Le recomiendo tener un resumen del libro, hecho por usted, disponible, según el asigna los capítulos usted hace el resumen, tome captura de las respuestas de TODOS los quices y guárdelas, algunas se repiten en los exámenes.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd8d45a77e02d7d434d8695eb24a5a066ffeebb658bb7dc9c6d670973c4446770'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'El curso en modalidad virtual se basa en leer capítulos de un libro. Las clases son lentas y las presentaciones poco claras. Mi recomendación es que haga las tareas bien y para cada examen llevar las respuestas de los quices anteriores. Los quices y los exámenes son confusos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '35c061fc28d3b9db08071078c747e002fd3e8c0cca8ef332b0841e2fe448be04'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '8b03d469220ad2c8788ed03545d7e94cabe67ef834abe2c16cc74a9c36e8cc73'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Se limita a darnos unas lecturas semanales las cuales son extraidas de algun curso, explica muy poco. Si le pides ayuda, el esta abierto a ayudar pero realmente como profesor su aporte es bastante bajo. Si usted quiere aprender por su cuenta lleve con este profe.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'f514c2f0dc99e65ae70f3dcda485645abcf97e19185c1c14f75b734a3e8d6843'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'No el peor profesor, pero si la peor clase de compu, le recomiendo que tenga una colección de las respuestas de quices porque o si no es imposible pasar. Ayúdense como grupo lo más que puedan y trate de sacar todos los puntos en tareas. Sus presentaciones son confusas y cuesta estudiar'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2023-04-22T00:00:00+00:00'::TIMESTAMPTZ, 'ac4fb56ddd71d4d60de4fe767e4b50c57e3062cc6c36a2e380e62270fb4aca47'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Pesimo profesor, las clases son larguisimas y tediosas, lo unico que hace es transcribir el libro y presentarlo en power point, se nota que solamente tiene experiencia dando el curso y se sabe los ejemplos del librofuera de ahí divaga demasiado y no logra explicar bien.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2023-03-10T00:00:00+00:00'::TIMESTAMPTZ, '588466f971737e28a30038aa60f658ee22ee13e5273360123635ff4b598477d4'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, '10 quices y 5 tareas si llegas a faltar en algo tenga por seguro que no pasa, haciendo todas las tareas con 50 en los examenes se pasa, pero los examenes son super engañosos agarra preguntas de los quices pero edita las opciones para que al final 10 de 15 preguntas sean "ninguna de las anteriores"'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e2a7edcb56dd1d20f60edee7661476e2fadbbd607fb44b0fdba94b37fc3be7da'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'El curso se basa en leer un libro y escuchar al profe hablar sobre la lectura de la semana, los quices y exámenes son muy confusos y las tareas no siempre las califica de la misma manera. No es mal profe pero hay aspectos que harían la clase más interesante.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1d69a15e32a45bb18928ee39d705b72a1a888435c49d85deae56cbcd9d081a67'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Las clases se hacen muy pesadas, ya que habla con tono monótono y solo se dedica a leer extractos de un libro en inglés que ud tiene que leer entero. Deja 10 quices y 4 tareas en las que hay que rogar para que le ayude. Exámenes difíciles, evítelo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, '655eb94140ebc9761ec227f1829d8dd67a378645297d8ef699186f4789bf4364'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Mal profesor. Sus clases se basan en decir lo mismo que un libro. Antes de semana 6 ya se conectaban menos de 8 estudiantes de todo el grupo. No aclara dudas, más bien lo manda a leer de vuelta. Quices confusos y examenes hechos para quedar al estudiante. Profesor que se cree dios y no sabe nada.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '704cd9032016d882c40941e12bd08e59e4e35a62183288fdb97f240e8ec19942'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'la materia es toda de un libro en ingles el cual espera que hayamos leido aunque no haya tiempo posible para eso. Lo que hace en las clases es volver a leer los capitulos anteriores del libro sin explicar nada con sus propias palabras. Los proyectos y examenes son demasiado dificiles. terrible.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-05-19T00:00:00+00:00'::TIMESTAMPTZ, '89207c4301b4b9ccaff52a1fd42eec6e8ec40dc45ac671f620dcb220ad28b0b2'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'La materia es toda de un libro en línea en inglés y hay que dedicarle aún más tiempo para comprenderla bien. Los quices y labs son demasiado fáciles, pero los examenes y proyectos son demasiado difíciles. Si lleva otros cursos pienselo mejor porque se le va a ir mucho tiempo en este.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'd77c4c26e7cbdb19d2f083a863bbf1d6cef7e0e22f7055a3a3642a53fc7ea0e2'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Deja muchas cosas para leer, que no da tiempo, habria que ponerle dema. No da puntos aunque sean décimas para pasar. Espera que uno estudie toda la materia, y no se puede, prefiero profesores vagos.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-04-14T00:00:00+00:00'::TIMESTAMPTZ, 'afd5deef614b0df037d0f6c65b06934fc83c26230e6c2af52a97cf55a5c8d377'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Muy buen profesor, ordenado, responsable. No deja pasar a los que no estudian.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'ea6fccc0306c3019b7cc1055053fa4d323de8ff920078cd7462bc29e900c4834'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Tiene que usar su propio tiempo en el curso por que el no da absolutamente nada de clases todo se hace con un libro, los quices son faciles, los proyectos y exámenes son muy dificiles. Si no tiene un respectivo tiempo de estudio no se pasa. Al final hizo curva por que solo pasaron 4 personas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '770964766b62e63fbf2412ab288559fb1507e5019a2ad170e4478978b39ceff6'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, '(Virtual) No dío clases, en cambio había que hacer las lecturas de un libro interactivo que se podían hacer en cualquier momento hasta la fecha límite. Lo único sincrónico eran los quices, laboratorios (estos dos en el mismo día) y los exámenes. Si usted es autodictaca se lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'db7f43be265061ae423d06e4cd7dfccb87996a9bc65fdda52c9d41c5be805c57'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Es muy organizado con las fechas de las evaluaciones. Hace 2 exámenes, los cuales son una combinación de las preguntas de los 10 quices (5 por examen). Deja 5 tareas, las cuales son muy fáciles de hacer y da bastante tiempo. No se hacen proyectos. No se aprende mucho, pero se pasa fácilmente.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3e309e4d790f6bc55b257cbba8b6bdadf9df79abbaf42dcf86bcd3957950a148'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Hace dos exámenes que son una combinación de los quices que hizo. Las clases son extremadamente aburridas y lentas. Les recomiendo grabar la clase y luego verla en 2x. Tambien hace 5 tareas en las cuales se obtiene 100 con hacerlas completas. No es tan mal profe, pero tampoco es buenísimo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '26fb46e503487debd4ae4cd2654c7c51d26295c6c800df8fd093e65ca8b7e193'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'No es claro con las evaluaciones, no diré nada de sus clases porque no dio clases, es demasiado vago y el proyecto lo agarró de Internet y lo tradujo y nunca dio especificaciones claras, es maleducado y trata mal a los estudiantes, llevar clases con él es una tortura.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '22475828c525d051da910ac1c9bfd2a0bb08761bcf355e90328fc4c9ff1f23e2'::TEXT, ARRAY[1249]::BIGINT[]),
    (306::BIGINT, 'Los exámenes son difíciles y las clases aburridas. El profe se enreda demasiado explicando, a veces no sabe de lo que habla, se nota porque cuando uno pregunta saca una respuesta a medias. Los proyectos son volados pero deja una tarea extra con la que se pasa el curso.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-10-02T00:00:00+00:00'::TIMESTAMPTZ, 'd75278b375977efb5be9902e5a5bc033af414433118a7e145fa087fc1041cef9'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Es fácil pasar el curso, sin embargo es muy aburrido y no sabe explicar claramente, únicamente lee de las presentaciones. Los exámenes son muy difíciles pero los proyectos son interesantes y sencillos si uno le pone.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '90b32ddeeacb60d77085779997b81879a3dd18eade358643d49125de1c86ddf8'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Curso se pasa fácil, solo es hacer todos los trabajos que deja, exámenes difíciles a pesar de que son de selección única, da bastante material extra para complementar la materia, a veces se enreda solo pero no es lo usual'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'eb5d6e259e62e8f5fb1f61deea838dfb16ccff6ee0212f533b4f56e804a5b29a'::TEXT, ARRAY[1035]::BIGINT[]),
    (306::BIGINT, 'Super aburrido, da un trabajo extra si el grupo entero necesita ayuda pero no brinda ayuda individual. Si hace todo se pasa facil. Examenes muy duros'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-09-27T00:00:00+00:00'::TIMESTAMPTZ, '99151cfed7591d2f614edbce94b5219a7c705667aeefe27ffba1b4a8f4b866eb'::TEXT, ARRAY[1045]::BIGINT[]),
    (306::BIGINT, 'El profesor es buena gente, sin embargo, le falta conocimiento del tema, las dudas en clases generalmente terminan con un !tendría que buscar¡. Exámenes difíciles, y los proyectos los hace el asistente, que califica según todo su "increible, extenso, gigantesco e indudable conocimiento".'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-31T00:00:00+00:00'::TIMESTAMPTZ, '3150c3156dda0e9118e6641b957a325aa1f8cf7684114a36a3f0b9ce5049e978'::TEXT, ARRAY[1043]::BIGINT[]),
    (306::BIGINT, 'Solo llega a leer presentaciones lo que hace que las clases sean super aburridas, examenes impasables, proyectos faciles y ni el sabe que entra en los quices del curso.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b3b57acd32bc4590b3eba01e957a95c20f30c9394b35076c9ec615af3ef60251'::TEXT, ARRAY[1047]::BIGINT[]),
    (306::BIGINT, 'Demasiado aburrido. Leer presentaciones desde el escritorio no deberia ser considerado como dar clases. Los proyectos eran resolver acertijos, lo cual en ninguno de los casos beneficio a aprender sobre los diferentes lenguajes de programacion. El examen rudo, los quizes faciles.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5b2956e3f4c9816a6a34febe6e76e669ea24ffb966e01abae6091ec6e475b76f'::TEXT, ARRAY[1046]::BIGINT[]),
    (306::BIGINT, 'El profesor se dedica a leer presentaciones todas las clases, por lo que son super aburridas. Los proyectos largos y complejos, aparte que el asistente: Luis Castillo super pedante con complejo de superioridad (Nunca más un curso con ese mae de asistente). Examenes super dificiles y poco claros'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3dd70021670aed8e837e1ccfc37350bfb4d9aa2ba74fce6c92192fdf82c5bedc'::TEXT, ARRAY[1065]::BIGINT[]),
    (306::BIGINT, 'Aburrido como él solo. Las presentaciones no son ni de él, la clase es eterna. Tampoco es tan malo, porque sabe lo suficiente del tema. Exámenes difíciles, pero eventualmente regala el curso al punto de que todos pasamos, la mitad con 100 en la nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Da crédito extra']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8a7075fc645a807efc1fb84e1fdd734d2a435e0425167a35577ac75ff0ec2d6a'::TEXT, ARRAY[1047]::BIGINT[]),
    (306::BIGINT, 'Se dedica a leer presentaciones, exámenes difíciles, en los proyectos el asistente era prácticamente el que mandaba.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '35e02ff9e18ceaf803709eab1c3a76f6add70d3c5d70f2707d00f49b6a6dd49d'::TEXT, ARRAY[1043]::BIGINT[]),
    (306::BIGINT, 'Clases muy aburridas porque se dedica a leer diapositivas. Los exámenes incluyen mucha materia de los libros (que no son pocos). Los proyectos y tareas son fáciles de hacer. El curso se pasa fácil, pero es aburrido. Dio muchísimos puntos extra.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0b04f063049e01efc1aae0af702a483262df86fda74701e0967461eee0fe8098'::TEXT, ARRAY[1047]::BIGINT[]),
    (306::BIGINT, 'El asistente califica a gusto "siguiendo" la rubrica, las clases son sumamente aburridas, examenes de 30 preguntas con marque con X pueden haber varias correctas pero la correcta es la mas "optima" segun él, las tareas cortas son como proyectos y no sabe ni lo que esta leyendo como "clase"'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bcf39ab57ed0ab2590bd877cbf7b154b5acc49f7f5f55611223f6007de5a50cb'::TEXT, ARRAY[1043]::BIGINT[]),
    (306::BIGINT, 'Clases aburridas y no obligatorias. Dio pts extra porque todo el mundo estaba mal. El asistente lo manipula mucho con las progras. Exámenes impasables.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '79d2fe5e92e282750dbab8382b9b3f3a8b42f3d16c0eede2f133340463a268d6'::TEXT, ARRAY[1065]::BIGINT[]),
    (306::BIGINT, 'Bueno: da pts extra si el grupo va muy mal, progras relativamente faciles Malo: examenes impasables, el profe no sabe nada de las progras por lo que hay que preguntar al asistente Luis como va a revisar si no te va muy mal, la clase es un karaoke de presentaciones, progras nada interesantes.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8dc21b6af7f5f8deba0767c1a044f146596e9b06c71886b6a42484cb2318c07b'::TEXT, ARRAY[1065]::BIGINT[]),
    (306::BIGINT, 'Clase super aburrida, la mayoria de compañeros estaban con su celular o computadora para no dormirse en la clase, te pone a investigar sobre muchas cosas diferentes y los exámenes son muy confusos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a62991372ddce40bb9034b37cff0f2db85384ac66716be048c0e0bb33f935409'::TEXT, ARRAY[1043]::BIGINT[]),
    (306::BIGINT, 'Buen profesor, ordenado, puntual, explica toda la materia y el curso queda bien completo. Proyectos pasables y exámenes rudos de selección porque son más complicados de lo normal, pero si se sabe bien la materia todo bien. Super recomendado!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2018-01-05T00:00:00+00:00'::TIMESTAMPTZ, '40c9305d65cef1453f8f7ac52eefa48842a1d6c04f3fff6a68739b13c99a83e4'::TEXT, ARRAY[1029]::BIGINT[]),
    (306::BIGINT, 'Súper ordenado. Quices semanales. Buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e9365db7f1f6590f8da32b4e1c8a81a0f90c94057df1f390fe84513ebfda9f04'::TEXT, ARRAY[1046]::BIGINT[]),
    (306::BIGINT, 'Muy buen profe, la nota la tiene muy distribuida por lo tanto es muy difícil quedarse, ayuda mucho en los proyectos y explica bien, solo que las clases son aburridas. Quices y tareas todas las semanas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'dfc1b73f2dbe37e6a0cf76b56069320a56574315ccc0b977e57fb60ae05eaae2'::TEXT, ARRAY[1046]::BIGINT[]),
    (306::BIGINT, 'Es el mejor profe, los proyectos son muy realizables y ayuda mucho por lo tanto solo las personas vagas no pasan con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-07T00:00:00+00:00'::TIMESTAMPTZ, '7fa27c83bcbcfd09acae543fae9ac1c7186a288b99a656d959ea942562a276cb'::TEXT, ARRAY[1046]::BIGINT[]),
    (306::BIGINT, 'Excelente profesor: Ordenado, ayuda mucho, le importa que uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, '1417aac3e545d67240635337f1715992c1338ee551eb882e37488520762ca6ca'::TEXT, ARRAY[1046]::BIGINT[]),
    (306::BIGINT, 'Sus clases son algo aburridas, pero si se le pone atención se entiende toda la materia, explica bastante claro y responde todas las dudas. Ayuda mucho con los proyectos. Quices y tareas semanales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '2c744421b6065310750ff48ac5e1388e108dcf039a98a53306a1a6529e8c257c'::TEXT, ARRAY[1046]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
